#!/usr/bin/env bash
# Run this from the ROOT of your React Native project (where package.json lives).
set -e
echo "Writing integration files..."
mkdir -p api context

echo "  api/client.js"
mkdir -p "$(dirname 'api/client.js')"
echo '' | base64 --decode > 'api/client.js'

echo "  api/auth.js"
mkdir -p "$(dirname 'api/auth.js')"
echo '' | base64 --decode > 'api/auth.js'

echo "  context/AuthContext.js"
mkdir -p "$(dirname 'context/AuthContext.js')"
echo '' | base64 --decode > 'context/AuthContext.js'

echo "  screens/CreateProfileScreen.js"
mkdir -p "$(dirname 'screens/CreateProfileScreen.js')"
echo '' | base64 --decode > 'screens/CreateProfileScreen.js'

echo "  screens/LoginScreen.js"
mkdir -p "$(dirname 'screens/LoginScreen.js')"
echo '' | base64 --decode > 'screens/LoginScreen.js'

echo "  App.js"
mkdir -p "$(dirname 'App.js')"
echo '' | base64 --decode > 'App.js'

echo "Installing new dependencies (axios + async-storage)..."
npx expo install axios @react-native-async-storage/async-storage

echo ""
echo "Done. Run npx expo start to test."
